package exercise

import (
	"sync"
	"testing"
)

func TestCounterStartsAtZero(t *testing.T) {
	counter := NewCounter()

	if got := counter.Value(); got != 0 {
		t.Errorf("got %d, want 0", got)
	}
}

func TestCounterCountsItsIncrements(t *testing.T) {
	counter := NewCounter()

	counter.Inc()
	counter.Inc()
	counter.Inc()

	if got := counter.Value(); got != 3 {
		t.Errorf("got %d, want 3", got)
	}
}

func TestCounterLosesNoIncrementsRunConcurrently(t *testing.T) {
	const workers = 100
	const incrementsPerWorker = 1000

	counter := NewCounter()

	var wg sync.WaitGroup
	wg.Add(workers)

	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for j := 0; j < incrementsPerWorker; j++ {
				counter.Inc()
			}
		}()
	}

	wg.Wait()

	want := workers * incrementsPerWorker
	if got := counter.Value(); got != want {
		t.Errorf("got %d, want %d: increments were lost when they ran at the same time", got, want)
	}
}

